BEGIN;
create temp table assertion_count(n integer);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create temp table st(k text primary key,v jsonb);
insert into public.properties(id,org_id,name,property_type)values('ee440000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','Reviewed units SQL fixture','multifamily');
insert into public.property_chatbot_contexts(property_id,status,requires_review,context_markdown,last_generated_at)values('ee440000-0000-4000-8000-000000000001','current',false,'Earlier exact facts',clock_timestamp());
insert into public.documents(property_id,content,metadata)values('ee440000-0000-4000-8000-000000000001','Old generated pricing exact text','{"source":"property_units","category":"pricing"}'),('ee440000-0000-4000-8000-000000000001','Original staff policy','{"source":"pasted_text","category":"pricing"}');
create function pg_temp.read_unit(u uuid default'ee440000-0000-4000-8000-000000000010',v uuid default null)returns jsonb language sql as $$select public.read_property_unit_review('ee440000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('kind','unit','unitId',u,'versionId',v))$$;
create function pg_temp.data()returns jsonb language sql as $$select jsonb_build_object('canonicalKey','studio-zero','name','Exact studio','bedrooms',0,'bathrooms',null,'sqftMin',500,'sqftMax',null,'priceMin',0,'priceMax',null,'deposit',0,'available',0,'specials','Confirmed zero example','sourceLabel','Staff confirmation','sourceUrl','https://example.invalid/source','sourceNote','Private exact staff quote 🏡','observedAt','2026-09-01T00:00:00Z','effectiveAt',null,'expiresAt',null)$$;
create function pg_temp.draft(u uuid default null,copy_from uuid default null)returns jsonb language sql as $$select jsonb_build_object('unitId',u,'copiedFromVersionId',copy_from,'expectedDraftId',v->'workspace'->'latest_version_id','expectedDecisionId',v->'workspace'->'last_decision_id','expectedUnitHash',case when u is null then public.knowledge_hash('null')else v->>'unitHash'end,'data',pg_temp.data(),'reason','Review synthetic exact pricing source')from(select pg_temp.read_unit(u)v)x$$;
create function pg_temp.save(i uuid,b jsonb)returns jsonb language sql as $$select public.save_property_unit_draft(i,'ee440000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',b)$$;
create function pg_temp.command(op text,u uuid default'ee440000-0000-4000-8000-000000000010',version uuid default null)returns jsonb language sql as $$select jsonb_build_object('operation',op,'unitId',u,'versionId',v->'version'->>'id','expectedDraftId',v->'workspace'->'latest_version_id','expectedAppliedId',v->'workspace'->'applied_version_id','expectedDecisionId',v->'workspace'->'last_decision_id','expectedUnitHash',v->>'unitHash','dataHash',v->'version'->>'data_hash','confirmed',true,'reason','Review exact synthetic floor-plan decision')from(select pg_temp.read_unit(u,version)v)x$$;
create function pg_temp.release(i uuid,b jsonb)returns jsonb language sql as $$select public.release_property_unit(i,'ee440000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',b)$$;
insert into st values('new',pg_temp.draft());
select pg_temp.check_it(pg_temp.save('ee440000-0000-4000-8000-000000000010',(select v from st where k='new'))->>'state'='saved','new draft saved');
select pg_temp.check_it(pg_temp.save('ee440000-0000-4000-8000-000000000010',(select v from st where k='new'))->>'state'='replayed','lost save reply replays');
select pg_temp.check_it(pg_temp.save('ee440000-0000-4000-8000-000000000010',(select v||'{"reason":"Changed intent"}'from st where k='new'))->>'state'='request_conflict','changed request cannot overwrite');
select pg_temp.check_it(not exists(select 1 from public.property_units where property_id='ee440000-0000-4000-8000-000000000001'),'draft creates no current unit');
select pg_temp.check_it((select status='current'and context_markdown='Earlier exact facts'from public.property_chatbot_contexts where property_id='ee440000-0000-4000-8000-000000000001'),'private draft leaves current facts intact');
select pg_temp.check_it((select count(*)from public.documents where property_id='ee440000-0000-4000-8000-000000000001')=2,'private draft preserves source docs');
insert into st values('approve',pg_temp.command('approve'));
select pg_temp.check_it(pg_temp.release(gen_random_uuid(),(select v||jsonb_build_object('dataHash',repeat('0',64))from st where k='approve'))->>'state'='draft_changed','wrong data hash held');
select pg_temp.check_it(pg_temp.release(gen_random_uuid(),(select v||jsonb_build_object('expectedUnitHash',repeat('0',64))from st where k='approve'))->>'state'='unit_changed','wrong current hash held');
create function pg_temp.fail_unit_review()returns trigger language plpgsql as $$begin if new.action='property.unit.approved'then raise exception 'Synthetic approval history failure';end if;return new;end$$;
create trigger fixture_unit_review_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_unit_review();
do $$begin begin perform pg_temp.release('ee440000-0000-4000-8000-000000000029',(select v from st where k='approve'));raise exception 'Expected rollback'using errcode='P0002';exception when sqlstate'P0001'then if sqlerrm<>'Synthetic approval history failure'then raise;end if;perform pg_temp.check_it(true,'history failure reaches atomic boundary');end;end$$;
drop trigger fixture_unit_review_failure on public.shared_action_events;
select pg_temp.check_it(not exists(select 1 from public.property_units where property_id='ee440000-0000-4000-8000-000000000001')and(select count(*)from public.documents where property_id='ee440000-0000-4000-8000-000000000001')=2,'failed approval rolls back facts and source removals');
select pg_temp.check_it(pg_temp.release('ee440000-0000-4000-8000-000000000020',(select v from st where k='approve'))->>'state'='saved','approval saved');
select pg_temp.check_it(pg_temp.release('ee440000-0000-4000-8000-000000000020',(select v from st where k='approve'))->>'state'='replayed','approval reply recovers exact result');
select pg_temp.check_it((select bedrooms=0 and rent_min=0 and rent_max is null and deposit=0 and available_count=0 and bathrooms is null and source_identity='console-review'from public.property_units where id='ee440000-0000-4000-8000-000000000010'),'unknown and zero retained distinctly');
select pg_temp.check_it((select status='stale'and requires_review and context_markdown='Earlier exact facts'from public.property_chatbot_contexts where property_id='ee440000-0000-4000-8000-000000000001'),'approval invalidates but preserves earlier assistant text');
select pg_temp.check_it((select count(*)from public.documents where property_id='ee440000-0000-4000-8000-000000000001')=1 and exists(select 1 from public.documents where property_id='ee440000-0000-4000-8000-000000000001'and content='Original staff policy'),'only exact obsolete generated copies removed');
select pg_temp.check_it((select before_state->'retiredDerivedDocuments'->0->>'content'='Old generated pricing exact text'from public.property_unit_decisions where id='ee440000-0000-4000-8000-000000000020'),'full removed generated copy retained privately');
select pg_temp.check_it((select count(*)from public.property_price_history where property_unit_id='ee440000-0000-4000-8000-000000000010')=1,'price history saved once');
select pg_temp.check_it(pg_temp.read_unit()->'eligible'='true','zero-availability current unit represented truthfully');
select pg_temp.check_it(pg_temp.release(gen_random_uuid(),pg_temp.command('reject'))->>'state'='already_reviewed','approved version cannot be retroactively rejected');
select set_config('p11.unit_review_scope','',true);
do $$begin begin update public.property_units set rent_min=99 where id='ee440000-0000-4000-8000-000000000010';raise exception 'guard missing'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'unrecorded reviewed-unit update blocked');end;begin delete from public.property_units where id='ee440000-0000-4000-8000-000000000010';raise exception 'guard missing'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'reviewed unit cannot be deleted');end;begin insert into public.documents(property_id,content,metadata)values('ee440000-0000-4000-8000-000000000001','Late old sync','{"source":"property_units","category":"pricing"}');raise exception 'guard missing'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'late obsolete pricing writer blocked');end;begin update public.property_unit_versions set data='{}'where id='ee440000-0000-4000-8000-000000000010';raise exception 'guard missing'using errcode='P0002';exception when sqlstate'P0001'then perform pg_temp.check_it(true,'version history immutable');end;end$$;
insert into st values('beforeDraft',pg_temp.read_unit());
select pg_temp.check_it(pg_temp.save('ee440000-0000-4000-8000-000000000011',pg_temp.draft('ee440000-0000-4000-8000-000000000010','ee440000-0000-4000-8000-000000000010')||jsonb_build_object('data',pg_temp.data()||'{"priceMin":25}'))->>'state'='saved','revision saved privately');
select pg_temp.check_it(pg_temp.read_unit()->>'unitHash'=(select v->>'unitHash'from st where k='beforeDraft'),'private revision preserves approved facts');
select pg_temp.check_it(pg_temp.release('ee440000-0000-4000-8000-000000000021',pg_temp.command('reject'))->>'state'='saved','private draft rejected');
select pg_temp.check_it(pg_temp.read_unit()->>'unitHash'=(select v->>'unitHash'from st where k='beforeDraft'),'rejection does not retire approved facts');
select pg_temp.check_it(pg_temp.release(gen_random_uuid(),pg_temp.command('approve'))->>'state'='already_reviewed','rejected version needs a new draft before approval');
select pg_temp.check_it(pg_temp.save('ee440000-0000-4000-8000-000000000012',pg_temp.draft('ee440000-0000-4000-8000-000000000010','ee440000-0000-4000-8000-000000000010'))->>'state'='saved','historical version copied into current draft');
select pg_temp.check_it((select parent_version_id='ee440000-0000-4000-8000-000000000011'and copied_from_version_id='ee440000-0000-4000-8000-000000000010'from public.property_unit_versions where id='ee440000-0000-4000-8000-000000000012'),'parent revision and copied historical source are distinct');
select pg_temp.check_it(pg_temp.release('ee440000-0000-4000-8000-000000000022',pg_temp.command('approve'))->>'state'='saved','new exact review applied');
select pg_temp.check_it((select count(*)from public.property_price_history where property_unit_id='ee440000-0000-4000-8000-000000000010')=1,'unchanged price avoids fabricated price event');
insert into st values('beforeRetire',pg_temp.read_unit());
select pg_temp.check_it(pg_temp.release('ee440000-0000-4000-8000-000000000023',pg_temp.command('retire'))->>'state'='saved','retirement recorded');
select pg_temp.check_it(pg_temp.read_unit()->'eligible'='false','retired facts ineligible');
select pg_temp.check_it(pg_temp.release('ee440000-0000-4000-8000-000000000024',pg_temp.command('restore'))->>'state'='saved','explicit restoration recorded');
select pg_temp.check_it(pg_temp.read_unit()->'unit'->>'source_updated_at'=(select v->'unit'->>'source_updated_at'from st where k='beforeRetire'),'restoration does not invent new source freshness');
select pg_temp.check_it(public.cancel_unused_knowledge_decision('ee440000-0000-4000-8000-000000000010','ee440000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('inputHash',repeat('a',64),'reason','Cancel only unused request'))->>'decisionDomain'='property_units','cancel recovers a committed unit request');
select pg_temp.check_it(public.cancel_unused_knowledge_decision('ee440000-0000-4000-8000-000000000099','ee440000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('inputHash',repeat('a',64),'reason','Cancel only unused request'))->>'state'='cancelled','unused request cancelled');
select pg_temp.check_it(pg_temp.save('ee440000-0000-4000-8000-000000000099',pg_temp.draft())->>'state'='decision_cancelled','delayed cancelled draft cannot save');
select pg_temp.check_it(not public.validate_property_unit_data(pg_temp.data()||'{"bedrooms":null}')and not public.validate_property_unit_data(pg_temp.data()||'{"priceMin":2,"priceMax":1}')and not public.validate_property_unit_data(pg_temp.data()||'{"sourceUrl":"https://user:pass@example.invalid"}'),'native validation rejects unknown required beds, reversed price and credential URL');
select pg_temp.check_it(pg_temp.save(gen_random_uuid(),pg_temp.draft()||jsonb_build_object('data',pg_temp.data()||jsonb_build_object('observedAt',clock_timestamp()+interval'1 day')))->>'state'='source_date_future','future source confirmation held');
select pg_temp.check_it(not has_table_privilege('authenticated','public.property_units','update')and not has_table_privilege('authenticated','public.property_price_history','insert')and not has_table_privilege('anon','public.property_unit_versions','select'),'direct row mutation and private evidence closed');
select pg_temp.check_it(not has_function_privilege('authenticated','public.release_property_unit(uuid,uuid,uuid,jsonb)','execute'),'native release closed to direct client calls');
select pg_temp.check_it(not exists(select 1 from public.shared_action_events where property_id='ee440000-0000-4000-8000-000000000001'and training_eligible),'unit activity not training eligible');
select pg_temp.check_it(not exists(select 1 from public.shared_action_events where property_id='ee440000-0000-4000-8000-000000000001'and(request::text||result::text)like'%Private exact staff quote%'),'source quotes stay out of shared events');
do $$declare prior_role text;begin select role into prior_role from public.profiles where id='11111111-1111-1111-1111-111111111111';update public.profiles set role=null where id='11111111-1111-1111-1111-111111111111';perform pg_temp.check_it(pg_temp.save(gen_random_uuid(),pg_temp.draft())->>'state'='forbidden','current manager permission rechecked');perform pg_temp.check_it(pg_temp.read_unit()->'canManage'='false','read-only user cannot manage');update public.profiles set role=prior_role where id='11111111-1111-1111-1111-111111111111';end$$;
select pg_temp.check_it(public.read_property_unit_review('ee440000-0000-4000-8000-000000000001',gen_random_uuid(),'{}')->>'state'='forbidden','other actor cannot read property');
insert into public.property_units(id,property_id,org_id,canonical_key,unit_type,rent_min,bedrooms)values('ee440000-0000-4000-8000-000000000030','ee440000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','old-source','Legacy source',100,1);
select pg_temp.save('ee440000-0000-4000-8000-000000000031',pg_temp.draft('ee440000-0000-4000-8000-000000000030'));
update public.property_units set rent_min=200 where id='ee440000-0000-4000-8000-000000000030';
select pg_temp.check_it(pg_temp.release(gen_random_uuid(),pg_temp.command('approve','ee440000-0000-4000-8000-000000000030'))->>'state'='unit_changed','legacy source change after draft prevents overwrite');
select pg_temp.save('ee440000-0000-4000-8000-000000000032',pg_temp.draft('ee440000-0000-4000-8000-000000000030'));
select pg_temp.check_it(pg_temp.release(gen_random_uuid(),pg_temp.command('approve','ee440000-0000-4000-8000-000000000030'))->>'state'='duplicate_identity','another managed canonical identity cannot be overwritten');
select pg_temp.save('ee440000-0000-4000-8000-000000000040',pg_temp.draft()||jsonb_build_object('data',pg_temp.data()||jsonb_build_object('canonicalKey','expired-unit','expiresAt','2020-01-01T00:00:00Z')));
select pg_temp.check_it(pg_temp.release(gen_random_uuid(),pg_temp.command('approve','ee440000-0000-4000-8000-000000000040'))->>'state'='facts_expired','expired facts held');
update public.properties set property_type='condo'where id='ee440000-0000-4000-8000-000000000001';
select pg_temp.check_it(pg_temp.release(gen_random_uuid(),pg_temp.command('approve','ee440000-0000-4000-8000-000000000040'))->>'state'='property_type_changed','changed property type holds pricing basis');
update public.properties set property_type='multifamily'where id='ee440000-0000-4000-8000-000000000001';
select pg_temp.check_it(pg_temp.save(gen_random_uuid(),pg_temp.draft('ee440000-0000-4000-8000-000000000030','ee440000-0000-4000-8000-000000000010'))->>'state'='not_found','cannot claim another unit as copied source');
insert into st values('historyPage',public.read_property_unit_review('ee440000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"kind":"versions","unitId":"ee440000-0000-4000-8000-000000000010"}'));
insert into public.property_unit_versions(id,unit_id,property_id,org_id,actor_id,data,data_hash,base_unit,base_unit_hash)select md5('unit-version-'||n)::uuid,'ee440000-0000-4000-8000-000000000010','ee440000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111',pg_temp.data(),'fixture','null','fixture'from generate_series(1,1001)n;
select pg_temp.check_it(public.read_property_unit_review('ee440000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111',jsonb_build_object('kind','versions','unitId','ee440000-0000-4000-8000-000000000010','offset',20,'expectedHash',(select v->>'historyHash'from st where k='historyPage')))->>'state'='history_changed','version page refuses changed history');
insert into st values('versionTail',public.read_property_unit_review('ee440000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"kind":"versions","unitId":"ee440000-0000-4000-8000-000000000010","offset":1000}'));
select pg_temp.check_it(v->>'total'='1004'and jsonb_array_length(v->'items')=4 and v->'nextOffset'='null','complete version history beyond REST cap')from st where k='versionTail';
insert into public.property_unit_decisions(id,unit_id,property_id,org_id,actor_id,kind,input,input_hash,result)select md5('unit-decision-'||n)::uuid,'ee440000-0000-4000-8000-000000000010','ee440000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','11111111-1111-1111-1111-111111111111','fixture','{}','fixture','{}'from generate_series(1,1001)n;
insert into st values('decisionTail',public.read_property_unit_review('ee440000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"kind":"decisions","unitId":"ee440000-0000-4000-8000-000000000010","offset":1000}'));
select pg_temp.check_it((v->>'total')::int>1001 and jsonb_array_length(v->'items')=(v->>'total')::int-1000,'complete decisions beyond REST cap')from st where k='decisionTail';
insert into public.property_units(id,property_id,org_id,canonical_key,unit_type,bedrooms)select md5('unit-inventory-'||n)::uuid,'ee440000-0000-4000-8000-000000000001','22222222-2222-2222-2222-222222222222','fixture-'||n,'Fixture '||n,1 from generate_series(1,1001)n;
insert into st values('unitsTail',public.read_property_unit_review('ee440000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"offset":1000}'));
select pg_temp.check_it(v->>'total'='1004'and jsonb_array_length(v->'items')=4,'complete actual and private inventory beyond REST cap')from st where k='unitsTail';
select pg_temp.check_it(public.read_property_unit_review('ee440000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"search":"expired-unit"}')->>'total'='1','private canonical identifier searchable');
select pg_temp.check_it(public.read_property_unit_review('ee440000-0000-4000-8000-000000000001','11111111-1111-1111-1111-111111111111','{"search":"%"}')->>'total'='0','search is literal not SQL wildcard');
select pg_temp.check_it(not exists(select 1 from public.shared_jobs where property_id='ee440000-0000-4000-8000-000000000001'),'review has no provider or model jobs');
select n as passed_assertions from assertion_count;
ROLLBACK;
